import React, { useContext } from "react";
import SidebarTeacher from "../components/SidebarTeacher";
import { AuthContext } from "../context/AuthContext";
import "../global.css";
import "./Dashboard.css";

export default function TeacherProfile() {
  const { user } = useContext(AuthContext);

  return (
    <div className="dashboard-flex">
      <SidebarTeacher active="Profile" />

      <main className="dashboard-main">
        <header className="dashboard-header-row">
          <div>
            <h1 className="dashboard-title">{user?.name || 'Profile'}</h1>
            <p className="dashboard-subtitle">Your teacher profile details.</p>
          </div>
        </header>

        <section className="profile-card">
          <div className="header-profile-chip" style={{ marginBottom: 16 }}>
            <div className="chip-avatar">{(user?.name || "T")[0]}</div>
            <div className="chip-info">
              <span className="chip-name">{user?.name || "Teacher"}</span>
              <span className="chip-role">Teacher</span>
            </div>
          </div>

          <div className="profile-fields">
            <div><strong>Name:</strong> {user?.name || "-"}</div>
            <div><strong>Email:</strong> {user?.email || "-"}</div>
            <div><strong>Department:</strong> {user?.department || "-"}</div>
          </div>
        </section>
      </main>
    </div>
  );
}
